/**
 * Structural render tests for the playground exemplar templates.
 *
 * WHY THIS EXISTS. tests/quality/test-playground-standard.sh gates the
 * *greppable* rules (tokens present, reduced-motion block present, no
 * draggable="true"). It cannot tell whether the file actually RENDERS, because
 * bash has no DOM. So the structure everything is copied from -- six sections,
 * a chart plus a table twin per chart, a populated copy-prompt -- was verified
 * once by a throwaway script and then protected by nothing. An adversarial
 * review caught exactly that gap: "20 jsdom assertions" had no committed
 * artifact behind it.
 *
 * This lives in orchestkit-demos because jsdom resolves here (devDependency)
 * and this workspace's vitest suite runs in CI.
 */
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { JSDOM } from "jsdom";
import { beforeAll, describe, expect, it } from "vitest";

const EXEMPLARS = resolve(
  process.cwd(),
  "..",
  "src/skills/shared/assets/playground-exemplars",
);

/** Text a sighted user actually sees, EXCLUDING any <title> tooltip child. */
function visibleText(el: Element): string {
  return Array.from(el.childNodes)
    .filter((n) => n.nodeType === 3 /* TEXT_NODE */)
    .map((n) => n.textContent ?? "")
    .join("");
}

function render(file: string) {
  const html = readFileSync(resolve(EXEMPLARS, file), "utf8");
  const errors: string[] = [];
  const dom = new JSDOM(html, {
    runScripts: "dangerously",
    pretendToBeVisual: true,
  });
  dom.virtualConsole.on("jsdomError", (e: unknown) => errors.push(String(e)));
  return { doc: dom.window.document, errors, window: dom.window };
}

describe("plan-dashboard.template.html", () => {
  let doc: Document;
  let errors: string[];

  beforeAll(() => {
    const r = render("plan-dashboard.template.html");
    doc = r.doc as unknown as Document;
    errors = r.errors;
  });

  it("renders its committed sample state with no script errors", () => {
    expect(errors).toEqual([]);
    expect(doc.getElementById("pv-title")?.textContent).toBeTruthy();
  });

  it("emits all six canonical sections", () => {
    expect(doc.querySelectorAll("details.sec")).toHaveLength(6);
    // Anchor ids are the section-nav contract; renaming one breaks the header links.
    for (const id of ["s0", "s1", "s2", "s3", "s4", "s5"]) {
      expect(doc.getElementById(id), `missing section #${id}`).toBeTruthy();
    }
  });

  it("pairs every chart with a table twin", () => {
    const toggles = doc.querySelectorAll(".viewtoggle").length;
    expect(toggles).toBeGreaterThan(0);
    expect(doc.querySelectorAll(".chart svg")).toHaveLength(toggles);
    expect(doc.querySelectorAll(".table table")).toHaveLength(toggles);
  });

  it("labels every chart for screen readers", () => {
    const svgs = Array.from(doc.querySelectorAll(".chart svg"));
    for (const svg of svgs) {
      expect(svg.getAttribute("aria-label"), svg.outerHTML.slice(0, 80)).toBeTruthy();
    }
  });

  it("truncates long chart labels without losing the full value", () => {
    // Right-anchored labels grow leftwards off the viewBox, so an untruncated
    // long path is silently clipped and the chart misidentifies its own bar.
    // Measure the TEXT NODE, not textContent: textContent concatenates the
    // <title> tooltip and reports ~70 chars for a correctly truncated label.
    const labels = Array.from(doc.querySelectorAll(".chart text"));
    expect(labels.length).toBeGreaterThan(0);
    for (const el of labels) {
      expect(visibleText(el).length).toBeLessThanOrEqual(34);
    }
    // Anything truncated must keep the full string in a <title>.
    for (const el of labels) {
      if (visibleText(el).startsWith("…")) {
        expect(el.querySelector("title")?.textContent ?? "").not.toHaveLength(0);
      }
    }
  });

  it("starts on the chart view and switches to the table in one click", () => {
    const firstTable = doc.querySelector(".table") as HTMLElement | null;
    expect(firstTable).toBeTruthy();
    expect(firstTable!.hidden).toBe(true);
    const buttons = doc.querySelectorAll(".viewtoggle button");
    (buttons[1] as HTMLElement).click();
    expect(firstTable!.hidden).toBe(false);
    expect(buttons[1].getAttribute("aria-pressed")).toBe("true");
    expect(buttons[0].getAttribute("aria-pressed")).toBe("false");
  });

  it("ships a populated copy-prompt and a live region", () => {
    expect((doc.getElementById("pv-prompt")?.textContent ?? "").length).toBeGreaterThan(40);
    expect(doc.getElementById("pv-copy")).toBeTruthy();
    expect(doc.querySelector('[aria-live="polite"]')).toBeTruthy();
  });

  it("never turns state into markup", () => {
    // The renderer must use textContent/createElementNS. If it ever switches to
    // innerHTML, a title like "x<img onerror=...>" becomes a live element.
    expect(doc.querySelector(".card img, .lane img, .ba img")).toBeNull();
  });
});

describe("living-plan.template.html", () => {
  it("renders and emits a next-wave copy-prompt", () => {
    const { doc, errors } = render("living-plan.template.html");
    expect(errors).toEqual([]);
    expect(doc.querySelectorAll(".panel").length).toBeGreaterThan(0);
    const prompt = doc.getElementById("lpp-prompt")?.textContent ?? "";
    expect(prompt.length).toBeGreaterThan(40);
    // The no-fork contract is the whole point of a living plan; it must survive
    // into the prompt a human copies into the next session.
    expect(prompt).toContain("never fork");
  });
});
